      "question": "조건과 같은 업무시설에 연결송수관설비를 설치하려고 한다. 송수구의 가까운 곳에 표시해야 하는 송수압력범위(MPa)를 계산하시오.(다만, 10m=0,1MPa이다.) ○ 업무시설은 지상 15층/지하 5층으로 각 층의 바닥면적은 2,500㎡ 이다. ○ 특별피난계단은 2개가 설치되어 있으며, 그 외 소방시설은 관련법령에 따라 적법하게 설치되어 있다. ○ 각 층의 층고는 4m이며, 송수구 및 방수구는 화재안전기준의 가장 낮은 위치에 설한다. ○ 주어진 조건 외의 것은 고려하지 않는다.",
